// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import { ComboBox } from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';

// Simple list of options
const items = ['Option 1', 'Option 2', 'Option 3', 'Option 4'];

function App() {
  return (
    <div style={{ width: '300px', margin: '2rem' }}>
      {/*
        Note: We're NOT passing titleText or helperText, only id and placeholder.
        This reproduces the missing-label and invalid aria-owns/controls bugs.
      */}
      <ComboBox
        id="carbon-combobox-example"
        items={items}
        placeholder="Filter..."
        onChange={({ selectedItem }) => console.log('selected:', selectedItem)}
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
